use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{fs,path::{Path,PathBuf},collections::{BTreeMap,BTreeSet}};
const R:&str="/home/ubuntu/src/zopro-perf-work/coarse-proof-phase176";
fn r(p:impl AsRef<Path>)->PathBuf{Path::new(R).join(p)}fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn main(){assert!(!r("failure-review.json").exists());let mut ledger:BTreeSet<String>=serde_json::from_value(read(r("prior-proof-sha256.json"))).unwrap();assert_eq!(ledger.len(),30708);let mut pins=0;for name in["build-pins.json","link-pins.json","pins.json"]{for(p,h)in read(r(name)).as_object().unwrap(){assert_eq!(hash(p),h.as_str().unwrap());pins+=1;}}
 let plan=read(r("plan.json"));let mut successful=0;let mut failed=0;let mut inventory=vec![];let mut vk=None;
 for step in plan["steps"].as_array().unwrap(){let name=step["name"].as_str().unwrap();let path=r("runs").join(name);if !path.exists(){continue;}let e=read(path.join("exit.json"));for k in["stdout","stderr"]{assert_eq!(hash(path.join(format!("{k}.log"))),e[format!("{k}_sha256")].as_str().unwrap());}if e["success"]==true{assert_eq!(e["returncode"],0);successful+=1;}else{failed+=1;assert_eq!(name,"preflight-1x2-w32-ON");assert_eq!(e["returncode"],101);let log=fs::read_to_string(path.join("stderr.log")).unwrap();assert!(log.contains("required phase canonical")&&log.contains("left: 0")&&log.contains("right: 2"));}}
 assert_eq!(successful,4);assert_eq!(failed,1);assert!(!r("runs/result.json").exists());for p in["stat","perf"]{assert_eq!(fs::read_dir(r(p)).unwrap().count(),0);}let jobs=read(r("jobs.json"));for j in jobs.as_array().unwrap().iter().filter(|j|j["name"]=="preflight-1x2-w32-accepted"||j["name"]=="preflight-1x2-w32-OFF"){let n=j["name"].as_str().unwrap();let dir=Path::new(j["directory"].as_str().unwrap());let proof=dir.join("0.proof");assert_eq!(fs::metadata(&proof).unwrap().len(),164);assert_eq!(hash(dir.join("0.public")),j["case"]["public_sha256"]);let verified=fs::read_to_string(r(format!("runs/verify-{n}/stdout.log"))).unwrap();let rows=verified.lines().filter_map(|l|l.strip_prefix("VERIFIED ")).collect::<Vec<_>>();assert_eq!(rows.len(),1);let f=rows[0].split_whitespace().map(|l|l.split_once('=').unwrap()).collect::<BTreeMap<_,_>>();let h=hash(&proof);assert_eq!(f["proof_sha256"],h);assert_eq!(f["image_sha256"],j["case"]["image_sha256"]);assert_eq!(f["public_sha256"],j["case"]["public_sha256"]);if let Some(old)=&vk{assert_eq!(old,f["vk_sha256"]);}else{vk=Some(f["vk_sha256"].to_string());}assert!(ledger.insert(h.clone()));inventory.push(json!({"name":n,"proof_sha256":h,"public_sha256":f["public_sha256"],"image_sha256":f["image_sha256"],"vk_sha256":f["vk_sha256"],"verified":true}));}
 assert_eq!(ledger.len(),30710);let native=read(r("native/result.json"));let cubic=read(r("cubic/result.json"));let link=read(r("links/result.json"));for x in[native,cubic,link]{assert_eq!(x["status"],"complete");}
 fs::write(r("proof-sha256-after-failure.json"),serde_json::to_vec_pretty(&ledger).unwrap()).unwrap();fs::write(r("proof-inventory-after-failure.json"),serde_json::to_vec_pretty(&inventory).unwrap()).unwrap();let out=json!({"passed":true,"pin_occurrences":pins,"successful_native_commands":4,"successful_cubic_commands":1,"successful_link_commands":1,"successful_capture_commands":4,"failed_capture_commands":1,"failure":"enabled graph misses canonical phase before latency; small-core-entry worker boundary lacks explicit recorder transport","failure_is_diagnostic_attribution_not_failed_proof":true,"latency_callers_started":0,"PMU_or_cycles_recordings_started":0,"native_core_tests":129,"native_prover_raw_tests":2,"native_cubic_tests":6,"new_recorder_tests":4,"new_independent_exports":2,"prior_proof_count":30708,"independent_proof_count":30710,"internally_verified_SDK_requests_before_abort":9,"production_changed":false,"adopted":false,"goal_achieved":false,"all_initial_source_and_qualification_preserved":true});fs::write(r("failure-review.json"),serde_json::to_vec_pretty(&out).unwrap()).unwrap();println!("{out}");}
